<?php

declare(strict_types=1);

namespace App\Models;

use App\Support\Ids\HasPrefixedId;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Support\Carbon;

/** A signed-in device: a cookie session or a personal access token. */
/* @properties-start (generated by dev:model-docs) */
/**
 * @property string $id
 * @property string $user_id
 * @property string|null $session_id
 * @property int|null $token_id
 * @property string|null $device
 * @property string|null $location
 * @property string|null $ip_address
 * @property string|null $user_agent
 * @property string|null $device_fingerprint
 * @property bool $is_staff
 * @property bool $is_impersonation
 * @property string|null $impersonator_id
 * @property Carbon|null $last_active_at
 * @property Carbon|null $expires_at
 * @property Carbon|null $revoked_at
 * @property Carbon|null $created_at
 * @property Carbon|null $updated_at
 */
/* @properties-end */
class AuthSession extends Model
{
    use HasPrefixedId;

    protected static string $idPrefix = 'ses';

    protected $fillable = [
        'user_id', 'session_id', 'token_id', 'device', 'location', 'ip_address', 'user_agent', 'device_fingerprint',
        'is_staff', 'is_impersonation', 'impersonator_id', 'last_active_at', 'expires_at', 'revoked_at',
    ];

    protected function casts(): array
    {
        return [
            'last_active_at' => 'datetime',
            'expires_at' => 'datetime',
            'revoked_at' => 'datetime',
            'is_staff' => 'boolean',
            'is_impersonation' => 'boolean',
        ];
    }

    /** @return BelongsTo<User, $this> */
    public function user(): BelongsTo
    {
        return $this->belongsTo(User::class);
    }
}
